#!/usr/bin/env node
// Verify the shadow-cljs AOT compiler bundle against the legacy nbb pipeline.
// Usage: node scripts/verify-compiler-bundle.mjs --nbb <nbb-cli.js>
//
// For every bin/compiler/mithril-native-*.mjs CLI this runs the same input
// through the bundle CLI and through the legacy bin/mithril-native-*.cljk
// (nbb) CLI and requires:
//   * identical exit status; a nonzero status must be exactly 65 on BOTH
//     sides with an identical REFUSE code field (REFUSE\t<code>\t…)
//   * on success, byte-identical artifacts (single file or directory tree)
// Exits non-zero on any difference.
import {spawnSync} from 'node:child_process';
import {mkdtempSync, writeFileSync, existsSync, mkdirSync, rmSync, readFileSync, readdirSync, lstatSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {resolve, join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const nbbIdx = args.indexOf('--nbb');
if (nbbIdx < 0) throw Error('usage: verify-compiler-bundle.mjs --nbb <nbb cli.js>');
const nbb = resolve(args[nbbIdx + 1]);
if (!existsSync(nbb)) throw Error('nbb engine does not exist');
const dir = mkdtempSync(join(tmpdir(), 'compiler-verify-'));
const config = join(dir, 'offline.edn');
writeFileSync(config, `{:paths [${JSON.stringify(join(repo, 'src'))}]}`);
let failures = 0;
const fail = (name, msg) => { console.log(`FAIL ${name}: ${msg}`); failures++; };
const ok = (name, msg) => console.log(`ok ${name}: ${msg}`);

const refuseCode = (stderr) => (stderr.trim().split('\t')[1] || '').trim();

function tree(dirPath) {
  const out = {};
  const walk = (rel) => {
    for (const name of readdirSync(join(dirPath, rel))) {
      const p = join(rel, name);
      if (lstatSync(join(dirPath, p)).isDirectory()) walk(p);
      else out[p] = readFileSync(join(dirPath, p));
    }
  };
  walk('.');
  return out;
}
function sameTree(a, b) {
  const ta = tree(a), tb = tree(b);
  const ka = Object.keys(ta).sort(), kb = Object.keys(tb).sort();
  if (ka.join('\0') !== kb.join('\0')) return `file lists differ (${ka.length} vs ${kb.length})`;
  for (const k of ka) if (!ta[k].equals(tb[k])) return `${k}: ${ta[k].length}B vs ${tb[k].length}B`;
  return null;
}

// spec: {cli, input, mode: 'file'|'dir', refused?: bool}
// For dir mode both sides get their own fresh output directory.
function run(spec) {
  const bundleCLI = join(repo, 'bin/compiler', `${spec.cli}.mjs`);
  const legacyCLI = join(repo, 'bin', `${spec.cli}.cljk`);
  const src = spec.input;
  const flat = spec.name.replace(/[^A-Za-z0-9_.-]/g, '-');
  const bundleOut = join(dir, `${flat}-bundle${spec.mode === 'dir' ? '-dir' : '.out'}`);
  const nbbOut = join(dir, `${flat}-nbb${spec.mode === 'dir' ? '-dir' : '.out'}`);
  const outArgs = spec.mode === 'dir' ? ['--output-directory'] : ['--output'];
  const bundle = spawnSync(process.execPath, [bundleCLI, src, '--target', 'js', ...outArgs, bundleOut], {encoding: 'utf8'});
  const legacy = spawnSync(process.execPath, [nbb, '--config', config, '-cp', 'src', legacyCLI, src, '--target', 'js', ...outArgs, nbbOut], {encoding: 'utf8'});
  if (bundle.status !== legacy.status) return fail(spec.name, `exit ${bundle.status} vs ${legacy.status} (${bundle.stderr.trim()} vs ${legacy.stderr.trim()})`);
  if (bundle.status !== 0) {
    if (bundle.status !== 65) return fail(spec.name, `nonzero status ${bundle.status} is not REFUSE 65`);
    const a = refuseCode(bundle.stderr), b = refuseCode(legacy.stderr);
    if (a !== b) return fail(spec.name, `REFUSE code '${a}' vs '${b}'`);
    return ok(spec.name, `both REFUSE '${a}' (65)`);
  }
  const diff = spec.mode === 'dir' ? sameTree(bundleOut, nbbOut)
    : (readFileSync(bundleOut).equals(readFileSync(nbbOut)) ? null : 'bytes differ');
  if (diff) return fail(spec.name, `artifact mismatch — ${diff}`);
  ok(spec.name, `byte-identical${spec.mode === 'dir' ? ' tree' : ` (${readFileSync(bundleOut).length}B)`}`);
}

// Composition fixtures are generated by the qualification admission control
// (real two-producer chain), so the bundle is compared on the same inputs.
function compositionFixtures() {
  const fixtures = join(dir, 'composition');
  mkdirSync(fixtures);
  const r = spawnSync(process.execPath, [nbb, '--config', config, '-cp', 'src',
    join(repo, 'test/qualification/native-declaration-composition/controls/admission.cljk')],
    {encoding: 'utf8', env: {...process.env, MITHRIL_COMPOSITION_FIXTURES: fixtures}});
  if (r.status !== 0) throw Error(`composition fixture admission failed: ${r.stderr}`);
  return fixtures;
}

const cases = [
  {name: 'native-js/array', cli: 'mithril-native-js', input: join(repo, 'examples/native-js-array.mith'), mode: 'file'},
  {name: 'native-js/yaml-str', cli: 'mithril-native-js', input: join(repo, 'examples/native-js-yaml-str.mith'), mode: 'file'},
  {name: 'native-esm/cosmokit', cli: 'mithril-native-esm', input: join(repo, 'examples/native-js-cosmokit-esm.mith'), mode: 'dir'},
  {name: 'native-package/cosmokit', cli: 'mithril-native-package', input: join(repo, 'examples/native-js-cosmokit.mith'), mode: 'file'},
  {name: 'native-declarations/cosmokit', cli: 'mithril-native-declarations', input: join(repo, 'examples/native-js-cosmokit-declarations.mith'), mode: 'file'},
  {name: 'declaration-program/cordis', cli: 'mithril-native-declaration-program', input: join(repo, 'examples/native-js-cordis-declaration-program.mith'), mode: 'dir'},
];
// Stale-parser/refusal-code regressions: the same malformed input must
// produce status 65 with the SAME refusal code through both pipelines.
const metaRefused = join(dir, 'metadata-refused.mith');
writeFileSync(metaRefused, '^:x ' + readFileSync(join(repo, 'examples/native-js-array.mith'), 'utf8'));
const formCount = join(dir, 'form-count.mith');
writeFileSync(formCount, '(mithril/form:v1)\n' + readFileSync(join(repo, 'examples/native-js-array.mith'), 'utf8'));
cases.push(
  {name: 'native-js/metadata-refuse', cli: 'mithril-native-js', input: metaRefused, mode: 'file'},
  {name: 'native-js/form-count-refuse', cli: 'mithril-native-js', input: formCount, mode: 'file'},
  {name: 'declaration-program/metadata-refuse', cli: 'mithril-native-declaration-program', input: metaRefused, mode: 'dir'},
  {name: 'native-declarations/metadata-refuse', cli: 'mithril-native-declarations', input: metaRefused, mode: 'file'},
);

try {
  for (const c of cases) { try { run(c); } catch (e) { fail(c.name, e.message); } }
  try {
    const fixtures = compositionFixtures();
    run({name: 'declaration-composition/chain', cli: 'mithril-native-declaration-composition', input: join(fixtures, 'composition.mith'), mode: 'dir'});
    run({name: 'declaration-composition/unbound-refuse', cli: 'mithril-native-declaration-composition', input: join(fixtures, 'invalid-composition.mith'), mode: 'dir'});
  } catch (e) { fail('declaration-composition', e.message); }
} finally {
  rmSync(dir, {recursive: true, force: true});
}
if (failures) { console.log(`${failures} FAILURE(S)`); process.exit(1); }
console.log('All bundle parity checks passed.');
